function hideOverflowingButtons(t){const o=t.querySelectorAll("li");o.forEach(e=>e.style.display="");const r=t.getBoundingClientRect().right-30;if(o.forEach(e=>{e.getBoundingClientRect().right>r&&(e.style.display="none")}),o.length>1){const e=Array.from(o).filter(n=>n.style.display!=="none");e.length===1&&(e[0].style.display="none")}}function initStripeCustomButtons(){const t=document.querySelectorAll(".---stripe-custom-item--buttons ul");if(!t.length)return;t.forEach(e=>hideOverflowingButtons(e));let o;const r=new ResizeObserver(()=>{clearTimeout(o),o=setTimeout(()=>{t.forEach(e=>hideOverflowingButtons(e))},RESIZE_DEBOUNCE_MS)});t.forEach(e=>r.observe(e.closest(".---stripe-custom-item--buttons")))}function updateStripeCustomPadding(t){const o=Array.from(t.children).filter(n=>n.tagName==="ARTICLE");if(!o.length)return;const r=parseFloat(getComputedStyle(t).gap)||0;let e=0;o.forEach(n=>e+=n.offsetWidth),e+=r*(o.length-1),t.style.setProperty("--stripe-content-width",e+"px")}function initStripeCustomPadding(){const t=document.querySelectorAll(".stripe-custom .scrollable-line--list");if(!t.length)return;t.forEach(e=>updateStripeCustomPadding(e));let o;const r=new ResizeObserver(()=>{if(document.readyState!=="complete"){t.forEach(e=>updateStripeCustomPadding(e));return}clearTimeout(o),o=setTimeout(()=>{t.forEach(e=>updateStripeCustomPadding(e))},RESIZE_DEBOUNCE_MS)});t.forEach(e=>r.observe(e))}document.addEventListener("DOMContentLoaded",()=>{initStripeCustomButtons(),initStripeCustomPadding()});
